/**
 * A major/minor version – e.g. `{ major: 26, minor: 4 }` represents version 26.4.
 *
 * Either field is `NaN` when it could not be parsed from a version string – see {@link extractVersion}.
 *
 * @internal
 */
export interface Version {
    major: number;
    minor: number;
}

/**
 * Extracts the major and minor versions from a dot-separated version string. Any parts beyond the minor version are
 * ignored, and an absent minor version counts as 0 – so `26`, `26.0` and `26.0.1` all extract to
 * `{ major: 26, minor: 0 }`.
 *
 * @param version A dot-separated version string, e.g. `26.4`, `26.4.1` or `372`.
 * @returns The extracted version. Parts which cannot be parsed are `NaN`, so callers handling untrusted version strings
 * (e.g. anything parsed out of a userAgent string) should check for it.
 *
 * @internal
 */
export function extractVersion(version: string): Version {
    const [major, minor = 0] = version.split(".").map((part) => parseInt(part, 10));
    return { major, minor };
}

/**
 * Compares a version against a minimum version. Versions with a field which could not be parsed (i.e. `NaN` – see
 * {@link extractVersion}) are treated as older than every minimum, which lets callers fall back to whatever their more
 * conservative behavior is.
 *
 * @param version The version to test.
 * @param minimum The version to compare against.
 * @returns True if `version` is at least `minimum`.
 *
 * @internal
 */
export function isVersionAtLeast({ major, minor }: Version, { major: minMajor, minor: minMinor }: Version): boolean {
    if (Number.isNaN(major)) return false;
    if (major !== minMajor) return major > minMajor;
    return !Number.isNaN(minor) && minor >= minMinor;
}
